export const PROJECT_SOURCE_CODE = {
  "src/config.ts": "import React from 'react';\nimport {\n  Wrench,\n  Cog,\n  Zap,\n  Snowflake,\n  ScanLine,\n  Droplets,\n  Paintbrush,\n  CircleDot,\n  ShoppingBag,\n} from 'lucide-react';\n\nexport const BUSINESS = {\n  name: 'Tiwari Motors Smart Garage',\n  hindiName: 'तिवारी मोटर्स',\n  tagline: 'Aapki Car Ki Har Zarurat Ka Ek Hi Naam.',\n  phonePrimary: '8218766134',\n  phoneSecondary: '9554182727',\n  phonePrimaryIntl: '+918218766134',\n  phoneSecondaryIntl: '+919554182727',\n  whatsappNumber: '918218766134',\n  email: 'tiwarimotors25@gmail.com',\n  address: 'Hussenpur Khurd Chowk, Ambedkar Nagar, Uttar Pradesh – 224181',\n  hours: 'Monday – Sunday: 10:00 AM – 6:30 PM',\n  googleReviewUrl: 'https://share.google/y0p7E7BdyWeQg3lZR',\n};\n\nexport const MAP_QUERY = 'Tiwari Motors Smart Garage, Hussenpur Khurd Chowk, Ambedkar Nagar, Uttar Pradesh 224181';\n\nexport const MAPS = {\n  embedUrl: `https://www.google.com/maps?q=${encodeURIComponent(MAP_QUERY)}&output=embed`,\n  directionsUrl: `https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(MAP_QUERY)}`,\n};\n\nexport const LOGO_SRC = '/images/logo.jpeg';\nexport const GARAGE_PHOTO_SRC = '/images/garage-entrance.jpeg';\n\nexport const waLink = (message: string) =>\n  `https://wa.me/${BUSINESS.whatsappNumber}?text=${encodeURIComponent(message)}`;\n\nexport const scrollToSection = (id: string) => {\n  const el = document.getElementById(id);\n  if (!el) return;\n  const navHeight = 64;\n  const elementPosition = el.getBoundingClientRect().top;\n  const offsetPosition = elementPosition + window.pageYOffset - navHeight;\n  window.scrollTo({\n    top: offsetPosition,\n    behavior: 'smooth',\n  });\n};\n\nexport interface ServiceItem {\n  id: string;\n  name: string;\n  desc: string;\n  icon: React.ComponentType<{ size?: number; className?: string }>;\n}\n\nexport const SERVICES: ServiceItem[] = [\n  {\n    id: 'car-service',\n    name: 'Car Service & Repair',\n    desc: 'Routine service, oil change aur general repairs — sabhi car brands ke liye.',\n    icon: Wrench,\n  },\n  {\n    id: 'engine-work',\n    name: 'Engine Work',\n    desc: 'Engine diagnosis, overhauling aur performance repairs.',\n    icon: Cog,\n  },\n  {\n    id: 'car-electrical',\n    name: 'Car Electrical',\n    desc: 'Battery, wiring, lights aur complete electrical fault repair.',\n    icon: Zap,\n  },\n  {\n    id: 'ac-repair',\n    name: 'AC Repair',\n    desc: 'AC gas refill, cooling problems aur full AC system service.',\n    icon: Snowflake,\n  },\n  {\n    id: 'computer-scanning',\n    name: 'Computer Scanning',\n    desc: 'Modern OBD scanning se exact fault turant pata karein.',\n    icon: ScanLine,\n  },\n  {\n    id: 'foam-wash',\n    name: 'Foam Wash',\n    desc: 'Premium foam wash aur interior cleaning — car bilkul fresh.',\n    icon: Droplets,\n  },\n  {\n    id: 'denting-painting',\n    name: 'Denting & Painting',\n    desc: 'Dent removal, body work aur quality paint finish.',\n    icon: Paintbrush,\n  },\n  {\n    id: 'wheel-alignment',\n    name: 'Wheel Alignment & Balancing',\n    desc: 'Alignment, balancing aur tyre care — smooth drive ke liye.',\n    icon: CircleDot,\n  },\n  {\n    id: 'car-accessories',\n    name: 'Car Accessories',\n    desc: 'Quality accessories, experienced haathon se fitting.',\n    icon: ShoppingBag,\n  },\n];\n\nexport const QUICK_SERVICES = [\n  { name: 'Car Service', icon: Wrench },\n  { name: 'Electrical', icon: Zap },\n  { name: 'AC Repair', icon: Snowflake },\n  { name: 'Computer Scanning', icon: ScanLine },\n  { name: 'Foam Wash', icon: Droplets },\n  { name: 'Denting & Painting', icon: Paintbrush },\n  { name: 'Wheel Care', icon: CircleDot },\n  { name: 'Car Accessories', icon: ShoppingBag },\n];\n",
  "src/App.tsx": "import React, { useState, useEffect } from 'react';\nimport { Header } from './components/Header';\nimport { Hero } from './components/Hero';\nimport { Marquee } from './components/Marquee';\nimport { About } from './components/About';\nimport { Services } from './components/Services';\nimport { WhyUs } from './components/WhyUs';\nimport { HowItWorks } from './components/HowItWorks';\nimport { Gallery } from './components/Gallery';\nimport { Reviews } from './components/Reviews';\nimport { Booking } from './components/Booking';\nimport { Emergency } from './components/Emergency';\nimport { Contact } from './components/Contact';\nimport { Footer } from './components/Footer';\nimport { FloatingButtons } from './components/FloatingButtons';\nimport { OwnerEditModal } from './components/OwnerEditModal';\nimport { ClassicWebsite } from './components/ClassicWebsite';\nimport { OwnerProvider } from './context/OwnerContext';\nimport { scrollToSection } from './config';\nimport { Sparkles, Layers } from 'lucide-react';\n\nfunction MainLayout() {\n  const [selectedService, setSelectedService] = useState<string>('');\n  const [designVersion, setDesignVersion] = useState<'replicated' | 'classic'>(() => {\n    try {\n      const params = new URLSearchParams(window.location.search);\n      if (params.get('design') === '1' || window.location.hash === '#classic') {\n        return 'classic';\n      }\n      return (localStorage.getItem('tiwari_motors_design_version') as 'replicated' | 'classic') || 'replicated';\n    } catch {\n      return 'replicated';\n    }\n  });\n\n  useEffect(() => {\n    try {\n      localStorage.setItem('tiwari_motors_design_version', designVersion);\n    } catch {\n      // Ignore\n    }\n  }, [designVersion]);\n\n  const handleSelectService = (serviceName: string) => {\n    setSelectedService(serviceName);\n    scrollToSection('booking');\n  };\n\n  if (designVersion === 'classic') {\n    return (\n      <ClassicWebsite onSwitchDesign={() => setDesignVersion('replicated')} />\n    );\n  }\n\n  return (\n    <div className=\"min-h-screen bg-white text-[#111111] selection:bg-[#F58220]/20 selection:text-[#F58220]\">\n      {/* Design Switcher Bar (Easy 1-Click Toggle between First Design & Current Replicate) */}\n      <div className=\"bg-[#0c0c0c] text-zinc-300 text-xs py-1.5 px-4 border-b border-white/10 flex flex-wrap items-center justify-between gap-2 z-50 relative\">\n        <div className=\"flex items-center gap-2\">\n          <span className=\"w-2 h-2 rounded-full bg-emerald-400 animate-pulse\" />\n          <span className=\"font-semibold text-white\">\n            Live Preview: <strong className=\"text-[#F58220]\">Design 2 (Smart Garage Replicate)</strong>\n          </span>\n        </div>\n        <button\n          type=\"button\"\n          onClick={() => setDesignVersion('classic')}\n          className=\"inline-flex items-center gap-1.5 px-3 py-1 rounded-md bg-white/10 hover:bg-white/20 text-white font-semibold text-xs border border-white/15 transition-all cursor-pointer\"\n        >\n          <Layers size={13} className=\"text-[#F58220]\" />\n          <span>Dekhein Pehle Wali Website (Design 1)</span>\n        </button>\n      </div>\n\n      {/* Sticky Navigation Header */}\n      <Header />\n\n      {/* Main Page Sections */}\n      <main id=\"main-content\">\n        <Hero />\n        <Marquee />\n        <About />\n        <Services onSelectService={handleSelectService} />\n        <WhyUs />\n        <HowItWorks />\n        <Gallery />\n        <Reviews />\n        <Booking selectedService={selectedService} />\n        <Emergency />\n        <Contact />\n      </main>\n\n      {/* Footer */}\n      <Footer onSelectService={handleSelectService} />\n\n      {/* Floating Action Buttons */}\n      <FloatingButtons />\n\n      {/* Owner Control & Edit Panel */}\n      <OwnerEditModal />\n    </div>\n  );\n}\n\nexport default function App() {\n  return (\n    <OwnerProvider>\n      <MainLayout />\n    </OwnerProvider>\n  );\n}\n",
  "src/components/Header.tsx": "import React, { useState } from 'react';\nimport { Menu, X, Phone, Settings } from 'lucide-react';\nimport { LOGO_SRC, scrollToSection } from '../config';\nimport { useOwner } from '../context/OwnerContext';\n\nconst NAV = [\n  { id: 'home', label: 'Home' },\n  { id: 'services', label: 'Services' },\n  { id: 'about', label: 'About Us' },\n  { id: 'gallery', label: 'Gallery' },\n  { id: 'reviews', label: 'Reviews' },\n  { id: 'contact', label: 'Contact' },\n];\n\nexport const Header: React.FC = () => {\n  const [open, setOpen] = useState(false);\n  const { business, setIsEditModalOpen } = useOwner();\n\n  const go = (e: React.MouseEvent, id: string) => {\n    e.preventDefault();\n    setOpen(false);\n    scrollToSection(id);\n  };\n\n  return (\n    <header className=\"fixed top-0 inset-x-0 z-50 bg-[#111111]/95 backdrop-blur-md border-b border-white/10\">\n      {/* Notice Banner if configured */}\n      {business.noticeBanner && (\n        <div className=\"bg-gradient-to-r from-[#F58220] to-[#D96E14] text-white text-xs font-semibold py-1.5 px-4 text-center\">\n          <span>{business.noticeBanner}</span>\n        </div>\n      )}\n\n      <div className=\"max-w-7xl mx-auto px-4 sm:px-6 h-16 flex items-center justify-between gap-3\">\n        {/* Brand Logo & Name */}\n        <a\n          href=\"#home\"\n          onClick={(e) => go(e, 'home')}\n          className=\"flex items-center gap-2.5 shrink-0 group\"\n          data-testid=\"header-logo-link\"\n        >\n          <img\n            src={LOGO_SRC}\n            alt=\"Tiwari Motors logo\"\n            className=\"h-10 w-10 rounded-md bg-white object-cover shadow-sm group-hover:opacity-95 transition-opacity\"\n          />\n          <span className=\"leading-tight\">\n            <span className=\"block font-heading font-bold text-white text-sm sm:text-base\">\n              Tiwari Motors\n            </span>\n            <span className=\"block text-[10px] tracking-[0.28em] text-[#F58220] font-semibold uppercase\">\n              SMART GARAGE\n            </span>\n          </span>\n        </a>\n\n        {/* Desktop Navigation Links */}\n        <nav className=\"hidden md:flex items-center gap-6 lg:gap-8\">\n          {NAV.map((n) => (\n            <a\n              key={n.id}\n              href={`#${n.id}`}\n              onClick={(e) => go(e, n.id)}\n              className=\"text-sm font-medium text-zinc-300 hover:text-white transition-colors\"\n            >\n              {n.label}\n            </a>\n          ))}\n        </nav>\n\n        {/* Desktop Quick Actions */}\n        <div className=\"hidden sm:flex items-center gap-2.5\">\n          <button\n            type=\"button\"\n            onClick={() => setIsEditModalOpen(true)}\n            title=\"Owner Edit Mode\"\n            className=\"p-2 rounded-lg text-zinc-400 hover:text-[#F58220] hover:bg-white/5 transition-colors cursor-pointer\"\n          >\n            <Settings size={17} />\n          </button>\n\n          <a\n            href={`tel:${business.phonePrimaryIntl}`}\n            className=\"inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold text-zinc-200 hover:text-white bg-white/5 hover:bg-white/10 border border-white/10 transition-colors\"\n          >\n            <Phone size={14} className=\"text-[#F58220]\" />\n            <span>{business.phonePrimary}</span>\n          </a>\n\n          <a\n            href=\"#booking\"\n            onClick={(e) => go(e, 'booking')}\n            data-testid=\"header-book-btn\"\n            className=\"inline-flex items-center gap-1.5 px-3.5 py-1.5 rounded-lg text-xs font-semibold text-white bg-[#F58220] hover:bg-[#D96E14] transition-colors shadow-sm\"\n          >\n            <span>Book Service</span>\n          </a>\n        </div>\n\n        {/* Mobile Menu Trigger */}\n        <div className=\"flex md:hidden items-center gap-1\">\n          <button\n            type=\"button\"\n            onClick={() => setIsEditModalOpen(true)}\n            title=\"Owner Edit Mode\"\n            className=\"p-2 text-zinc-400 hover:text-[#F58220] transition-colors cursor-pointer\"\n          >\n            <Settings size={18} />\n          </button>\n          <button\n            type=\"button\"\n            onClick={() => setOpen(!open)}\n            className=\"p-2 text-zinc-300 hover:text-white hover:bg-white/10 rounded-lg transition-colors cursor-pointer\"\n            aria-label=\"Toggle menu\"\n          >\n            {open ? <X size={22} /> : <Menu size={22} />}\n          </button>\n        </div>\n      </div>\n\n      {/* Mobile Drawer */}\n      {open && (\n        <div className=\"md:hidden bg-[#111111] border-b border-white/10 px-4 py-4 space-y-3 animate-in slide-in-from-top-2 duration-200\">\n          <nav className=\"flex flex-col space-y-2\">\n            {NAV.map((n) => (\n              <a\n                key={n.id}\n                href={`#${n.id}`}\n                onClick={(e) => go(e, n.id)}\n                className=\"px-3 py-2 rounded-md text-sm font-medium text-zinc-300 hover:text-white hover:bg-white/5 transition-colors\"\n              >\n                {n.label}\n              </a>\n            ))}\n          </nav>\n\n          <div className=\"pt-3 border-t border-white/10 grid grid-cols-2 gap-2\">\n            <a\n              href={`tel:${business.phonePrimaryIntl}`}\n              className=\"flex items-center justify-center gap-1.5 py-2 px-3 rounded-lg text-xs font-semibold text-white bg-white/10 hover:bg-white/15 transition-colors\"\n            >\n              <Phone size={14} className=\"text-[#F58220]\" />\n              <span>Call Now</span>\n            </a>\n            <a\n              href=\"#booking\"\n              onClick={(e) => go(e, 'booking')}\n              className=\"flex items-center justify-center gap-1.5 py-2 px-3 rounded-lg text-xs font-semibold text-white bg-[#F58220] hover:bg-[#D96E14] transition-colors\"\n            >\n              <span>Book Service</span>\n            </a>\n          </div>\n        </div>\n      )}\n    </header>\n  );\n};\n",
  "src/components/Hero.tsx": "import React from 'react';\nimport { MessageCircle, Phone, ArrowRight, ShieldCheck, MapPin, Wrench, CheckCircle2 } from 'lucide-react';\nimport { GARAGE_PHOTO_SRC, scrollToSection, waLink } from '../config';\nimport { useOwner } from '../context/OwnerContext';\n\nexport const Hero: React.FC = () => {\n  const { business } = useOwner();\n\n  return (\n    <section\n      id=\"home\"\n      className=\"relative bg-[#111111] text-white pt-18 sm:pt-20 pb-8 sm:pb-10 overflow-hidden border-b border-white/10\"\n    >\n      {/* Subtle ambient lighting */}\n      <div\n        className=\"absolute -top-24 -right-24 w-80 h-80 rounded-full bg-[#F58220]/15 blur-3xl pointer-events-none\"\n        aria-hidden=\"true\"\n      />\n\n      <div className=\"relative max-w-7xl mx-auto px-4 sm:px-6\">\n        <div className=\"grid lg:grid-cols-12 gap-6 lg:gap-8 items-center\">\n          {/* Left Column: Headline & Compact Action */}\n          <div className=\"lg:col-span-7\">\n            {/* Badges */}\n            <div className=\"inline-flex items-center gap-2 mb-2.5\">\n              <span className=\"text-[11px] font-bold uppercase tracking-[0.2em] text-[#F58220] font-heading\">\n                {business.name}\n              </span>\n              <span className=\"text-white/30\">·</span>\n              <span className=\"text-[11px] font-medium text-zinc-300 bg-white/10 px-2 py-0.5 rounded border border-white/10\">\n                {business.hindiName}\n              </span>\n              <span className=\"hidden sm:inline-flex items-center gap-1 text-[11px] text-emerald-400 font-semibold bg-emerald-500/10 px-2 py-0.5 rounded border border-emerald-500/20\">\n                <span className=\"w-1.5 h-1.5 rounded-full bg-emerald-400 animate-pulse\" />\n                Workshop Open\n              </span>\n            </div>\n\n            {/* Main Headline - Compact & Balanced */}\n            <h1\n              className=\"font-heading font-extrabold text-2xl sm:text-4xl lg:text-[42px] tracking-tight leading-[1.15]\"\n              data-testid=\"hero-headline\"\n            >\n              “Aapki Car Ki Har Zarurat Ka{' '}\n              <span className=\"text-[#F58220] whitespace-nowrap\">Ek Hi Naam.”</span>\n            </h1>\n\n            {/* Sub-text */}\n            <p className=\"mt-2.5 text-xs sm:text-sm text-zinc-300 leading-relaxed max-w-xl\">\n              Complete multi-brand car service & repair in Ambedkar Nagar — Routine Maintenance, Computer Scanning, AC Repair, Foam Wash & Car Accessories.\n            </p>\n\n            {/* CTA Buttons */}\n            <div className=\"mt-4 sm:mt-5 flex flex-wrap items-center gap-2.5\">\n              <button\n                type=\"button\"\n                onClick={() => scrollToSection('booking')}\n                data-testid=\"hero-book-btn\"\n                className=\"inline-flex items-center justify-center gap-2 px-5 py-2.5 rounded-xl bg-[#F58220] hover:bg-[#D96E14] text-white text-xs sm:text-sm font-bold shadow-md shadow-[#F58220]/20 transition-all hover:-translate-y-0.5 cursor-pointer\"\n              >\n                <span>Book Service</span>\n                <ArrowRight size={15} />\n              </button>\n\n              <a\n                href={waLink('Namaste Tiwari Motors! Mujhe car service ke baare mein jaankari chahiye.')}\n                target=\"_blank\"\n                rel=\"noreferrer\"\n                data-testid=\"hero-whatsapp-btn\"\n                className=\"inline-flex items-center justify-center gap-1.5 px-4 py-2.5 rounded-xl bg-[#25D366] hover:bg-[#1fb857] text-white text-xs sm:text-sm font-bold shadow-sm transition-all hover:-translate-y-0.5\"\n              >\n                <MessageCircle size={16} />\n                <span>WhatsApp</span>\n              </a>\n\n              <a\n                href={`tel:${business.phonePrimaryIntl}`}\n                data-testid=\"hero-call-btn\"\n                className=\"inline-flex items-center justify-center gap-1.5 px-4 py-2.5 rounded-xl bg-white/10 hover:bg-white/15 text-white border border-white/15 text-xs sm:text-sm font-semibold transition-all hover:-translate-y-0.5\"\n              >\n                <Phone size={14} className=\"text-[#F58220]\" />\n                <span>{business.phonePrimary}</span>\n              </a>\n            </div>\n\n            {/* Trust points - Clean single inline bar */}\n            <div className=\"mt-4 pt-3.5 border-t border-white/10 flex flex-wrap items-center gap-x-4 gap-y-2 text-[11px] text-zinc-300 font-medium\">\n              <span className=\"flex items-center gap-1.5\">\n                <CheckCircle2 size={13} className=\"text-[#F58220]\" />\n                <span>Multi-Brand Expert</span>\n              </span>\n              <span className=\"flex items-center gap-1.5\">\n                <CheckCircle2 size={13} className=\"text-[#F58220]\" />\n                <span>Computer Diagnostics</span>\n              </span>\n              <span className=\"flex items-center gap-1.5\">\n                <CheckCircle2 size={13} className=\"text-[#F58220]\" />\n                <span>Genuine Spares</span>\n              </span>\n              <span className=\"flex items-center gap-1.5\">\n                <CheckCircle2 size={13} className=\"text-[#F58220]\" />\n                <span>Transparent Pricing</span>\n              </span>\n            </div>\n          </div>\n\n          {/* Right Column: Garage Entrance Photo (Balanced Height) */}\n          <div className=\"lg:col-span-5 relative\">\n            <div className=\"relative rounded-xl overflow-hidden border border-white/15 shadow-xl bg-neutral-900 group\">\n              <img\n                src={GARAGE_PHOTO_SRC}\n                alt=\"Tiwari Motors Smart Garage entrance in Ambedkar Nagar\"\n                className=\"w-full h-52 sm:h-64 lg:h-72 object-cover group-hover:scale-102 transition-transform duration-500\"\n              />\n              <div className=\"absolute inset-0 bg-gradient-to-t from-black/85 via-black/20 to-transparent pointer-events-none\" />\n\n              {/* Verified Location Card on Photo */}\n              <div className=\"absolute bottom-2.5 left-2.5 right-2.5 bg-[#181818]/90 backdrop-blur-md rounded-lg p-2.5 border border-white/15 flex items-center justify-between\">\n                <div className=\"min-w-0 pr-2\">\n                  <p className=\"text-[10px] font-bold uppercase tracking-wider text-[#F58220]\">\n                    Tiwari Motors Smart Garage\n                  </p>\n                  <p className=\"text-[11px] font-medium text-zinc-300 truncate flex items-center gap-1 mt-0.5\">\n                    <MapPin size={11} className=\"text-[#F58220] shrink-0\" />\n                    <span className=\"truncate\">{business.address}</span>\n                  </p>\n                </div>\n                <div className=\"shrink-0 flex items-center gap-1 text-[10px] font-bold text-white bg-white/10 px-2 py-1 rounded border border-white/10\">\n                  <ShieldCheck size={12} className=\"text-[#F58220]\" />\n                  <span>Verified</span>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n};\n",
  "src/components/Services.tsx": "import React from 'react';\nimport { ArrowRight } from 'lucide-react';\nimport { SectionHead } from './Reveal';\nimport { SERVICES } from '../config';\n\ninterface ServicesProps {\n  onSelectService: (serviceName: string) => void;\n}\n\nexport const Services: React.FC<ServicesProps> = ({ onSelectService }) => {\n  return (\n    <section id=\"services\" className=\"bg-white scroll-mt-20 py-8 sm:py-12 border-b border-zinc-200\">\n      <div className=\"max-w-7xl mx-auto px-4 sm:px-6\">\n        <SectionHead\n          eyebrow=\"What We Do\"\n          title=\"Our Services\"\n          subtitle=\"Routine maintenance se major repairs tak — aapki car ki poori dekhbhal.\"\n          testid=\"services-heading\"\n        />\n\n        {/* Compact Grid with tighter paddings & cleaner cards */}\n        <div className=\"mt-6 grid sm:grid-cols-2 lg:grid-cols-3 gap-3 sm:gap-3.5\">\n          {SERVICES.map((s) => {\n            const Icon = s.icon;\n            return (\n              <div\n                key={s.id}\n                className=\"bg-[#FAFAFA] hover:bg-white border border-zinc-200/90 hover:border-[#F58220]/50 rounded-xl p-4 sm:p-4.5 transition-all duration-200 hover:shadow-sm flex flex-col justify-between group\"\n              >\n                <div>\n                  <div className=\"flex items-center justify-between mb-2.5\">\n                    <span className=\"flex items-center justify-center w-9 h-9 rounded-lg bg-[#F58220]/10 text-[#F58220] group-hover:bg-[#F58220] group-hover:text-white transition-colors duration-200\">\n                      <Icon size={18} />\n                    </span>\n                    <span className=\"text-[10px] font-bold text-zinc-400 group-hover:text-[#F58220] uppercase font-mono tracking-wider\">\n                      Service\n                    </span>\n                  </div>\n\n                  <h3 className=\"font-heading font-bold text-sm sm:text-base text-[#111111] group-hover:text-[#F58220] transition-colors\">\n                    {s.name}\n                  </h3>\n                  <p className=\"mt-1 text-xs text-zinc-600 leading-relaxed line-clamp-2\">\n                    {s.desc}\n                  </p>\n                </div>\n\n                <div className=\"mt-3.5 pt-2.5 border-t border-zinc-200/60 flex items-center justify-between\">\n                  <button\n                    type=\"button\"\n                    onClick={() => onSelectService(s.name)}\n                    data-testid={`service-book-${s.id}`}\n                    className=\"inline-flex items-center gap-1 text-[11px] font-bold text-[#F58220] hover:text-[#D96E14] cursor-pointer\"\n                  >\n                    <span>Book Service</span>\n                    <ArrowRight size={13} className=\"group-hover:translate-x-1 transition-transform\" />\n                  </button>\n                  <span className=\"text-[10px] font-medium text-zinc-400 bg-zinc-100 px-1.5 py-0.5 rounded\">\n                    Multi-Brand\n                  </span>\n                </div>\n              </div>\n            );\n          })}\n        </div>\n      </div>\n    </section>\n  );\n};\n",
  "src/components/WhyUs.tsx": "import React from 'react';\nimport { Users, Car, ScanLine, Wrench, ShieldCheck, HeartHandshake } from 'lucide-react';\nimport { SectionHead } from './Reveal';\n\nconst ITEMS = [\n  {\n    icon: Users,\n    title: 'Experienced Team',\n    desc: 'Trained mechanics for multi-brand cars.',\n  },\n  {\n    icon: Car,\n    title: 'Multi-Brand Support',\n    desc: 'Maruti, Hyundai, Tata se Mahindra tak.',\n  },\n  {\n    icon: ScanLine,\n    title: 'Computer Diagnosis',\n    desc: 'OBD-II error check, no guesswork.',\n  },\n  {\n    icon: Wrench,\n    title: 'Complete Car Care',\n    desc: 'Service, AC, wash aur parts ek jagah.',\n  },\n  {\n    icon: ShieldCheck,\n    title: 'Modern Tools',\n    desc: 'Hydraulic lift, high-pressure foam wash.',\n  },\n  {\n    icon: HeartHandshake,\n    title: 'Fair Dealing',\n    desc: 'Clear estimation, genuine advice & spares.',\n  },\n];\n\nexport const WhyUs: React.FC = () => {\n  return (\n    <section id=\"why-us\" className=\"bg-[#111111] scroll-mt-20 py-8 sm:py-12 border-b border-white/10\">\n      <div className=\"max-w-7xl mx-auto px-4 sm:px-6\">\n        <SectionHead\n          eyebrow=\"Why Choose Us\"\n          title=\"Why Choose Tiwari Motors?\"\n          subtitle=\"Aapki gaadi ke liye sahi log, modern tools aur imaandar approach.\"\n          dark\n          testid=\"why-us-heading\"\n        />\n\n        {/* Compact Grid: 6 cards in a tight 2 or 3 col layout with compact padding */}\n        <div className=\"mt-6 grid grid-cols-2 sm:grid-cols-2 lg:grid-cols-3 gap-2.5 sm:gap-3.5\">\n          {ITEMS.map((item) => {\n            const Icon = item.icon;\n            return (\n              <div\n                key={item.title}\n                className=\"bg-white/[0.04] border border-white/10 hover:border-[#F58220]/50 rounded-xl p-3 sm:p-4 transition-all duration-200 hover:bg-white/[0.07] group flex items-start gap-3\"\n              >\n                <span className=\"flex items-center justify-center w-8 h-8 rounded-lg bg-[#F58220]/15 text-[#F58220] group-hover:bg-[#F58220] group-hover:text-white transition-colors shrink-0 mt-0.5\">\n                  <Icon size={16} />\n                </span>\n                <div className=\"min-w-0\">\n                  <h3 className=\"font-heading font-bold text-xs sm:text-sm text-white group-hover:text-[#F58220] transition-colors leading-snug\">\n                    {item.title}\n                  </h3>\n                  <p className=\"mt-0.5 text-[11px] text-zinc-400 leading-relaxed line-clamp-2\">\n                    {item.desc}\n                  </p>\n                </div>\n              </div>\n            );\n          })}\n        </div>\n      </div>\n    </section>\n  );\n};\n",
  "src/components/About.tsx": "import React from 'react';\nimport { CheckCircle2, Phone, Calendar } from 'lucide-react';\nimport { Reveal, SectionHead } from './Reveal';\nimport { GARAGE_PHOTO_SRC, scrollToSection } from '../config';\nimport { useOwner } from '../context/OwnerContext';\n\nconst POINTS = [\n  'Multi-Brand Service for all popular Indian & global car models',\n  'Advanced OBD-II Computer Diagnostics for accurate problem detection',\n  'Experienced and certified technicians for reliable work',\n  'Clear transparency in estimates with no hidden surprise costs',\n  'Comprehensive facility: Engine, Electrical, AC, Body Shop & Accessories',\n];\n\nexport const About: React.FC = () => {\n  const { business } = useOwner();\n\n  return (\n    <section id=\"about\" className=\"bg-[#F7F7F7] scroll-mt-20 py-14 sm:py-20 border-b border-zinc-200\">\n      <div className=\"max-w-7xl mx-auto px-4 sm:px-6 grid lg:grid-cols-2 gap-10 lg:gap-14 items-center\">\n        {/* Left Column: Real Garage Photo with Orange Accent Corner */}\n        <Reveal className=\"relative order-2 lg:order-1\">\n          <div\n            className=\"absolute -top-3 -left-3 w-24 h-24 border-t-4 border-l-4 border-[#F58220] rounded-tl-2xl\"\n            aria-hidden=\"true\"\n          />\n          <img\n            src={GARAGE_PHOTO_SRC}\n            alt=\"Tiwari Motors Smart Garage workshop in Ambedkar Nagar\"\n            loading=\"lazy\"\n            className=\"relative rounded-2xl border border-zinc-200 shadow-lg w-full aspect-square sm:aspect-[4/3] lg:aspect-square object-cover\"\n            data-testid=\"about-garage-image\"\n          />\n          {/* Badge over photo */}\n          <div className=\"absolute bottom-4 left-4 right-4 bg-white/95 backdrop-blur-md p-3 rounded-xl border border-zinc-200 shadow-md\">\n            <p className=\"text-xs font-bold text-zinc-900 font-heading\">\n              {business.name}\n            </p>\n            <p className=\"text-[11px] text-zinc-600\">\n              {business.address}\n            </p>\n          </div>\n        </Reveal>\n\n        {/* Right Column: Information & Points */}\n        <div className=\"order-1 lg:order-2\">\n          <SectionHead\n            eyebrow=\"About Tiwari Motors\"\n            title=\"Complete Car Care, Under One Roof\"\n            testid=\"about-heading\"\n          />\n\n          <Reveal delay={0.1}>\n            <p className=\"mt-4 text-sm sm:text-base text-zinc-600 leading-relaxed\">\n              Tiwari Motors Smart Garage is a multi-brand car service and repair workshop in Ambedkar Nagar providing reliable automotive solutions for everyday maintenance, mechanical repairs, electrical problems, AC issues, computer diagnosis, washing, body work and car accessories.\n            </p>\n          </Reveal>\n\n          <Reveal delay={0.18}>\n            <ul className=\"mt-6 space-y-3\">\n              {POINTS.map((p) => (\n                <li key={p} className=\"flex items-start gap-2.5 text-sm sm:text-base text-zinc-700\">\n                  <CheckCircle2\n                    size={18}\n                    className=\"text-[#F58220] mt-0.5 shrink-0\"\n                  />\n                  <span>{p}</span>\n                </li>\n              ))}\n            </ul>\n          </Reveal>\n\n          <Reveal delay={0.25} className=\"mt-8 flex flex-wrap items-center gap-3\">\n            <button\n              type=\"button\"\n              onClick={() => scrollToSection('booking')}\n              className=\"inline-flex items-center gap-2 px-5 py-2.5 rounded-lg bg-[#F58220] hover:bg-[#D96E14] text-white text-xs sm:text-sm font-bold shadow-sm transition-all cursor-pointer\"\n            >\n              <Calendar size={15} />\n              <span>Book an Inspection</span>\n            </button>\n\n            <a\n              href={`tel:${business.phonePrimaryIntl}`}\n              className=\"inline-flex items-center gap-2 px-4 py-2.5 rounded-lg bg-white hover:bg-zinc-100 text-zinc-900 border border-zinc-300 text-xs sm:text-sm font-semibold transition-all\"\n            >\n              <Phone size={15} className=\"text-[#F58220]\" />\n              <span>Call: {business.phonePrimary}</span>\n            </a>\n          </Reveal>\n        </div>\n      </div>\n    </section>\n  );\n};\n",
  "src/components/Gallery.tsx": "import React, { useState, useEffect, useMemo } from 'react';\nimport { X, ZoomIn, Plus, Trash2, ImagePlus, ArrowRight, ArrowLeft, Layers, Camera } from 'lucide-react';\nimport { SectionHead } from './Reveal';\nimport { GARAGE_PHOTO_SRC, LOGO_SRC } from '../config';\n\ninterface GalleryPhoto {\n  id: string;\n  src: string;\n  title: string;\n  category: string;\n  isUserUploaded?: boolean;\n}\n\ninterface CategoryFolder {\n  name: string;\n  hindiTitle: string;\n  coverImage: string;\n  description: string;\n  iconText: string;\n}\n\nconst DEFAULT_GALLERY: GalleryPhoto[] = [\n  {\n    id: 'g-1',\n    src: GARAGE_PHOTO_SRC,\n    title: 'Tiwari Motors Smart Garage – Entrance & Workshop Yard',\n    category: 'Garage & Facility',\n  },\n  {\n    id: 'g-2',\n    src: LOGO_SRC,\n    title: 'Tiwari Motors Smart Garage – Official Brand Identity',\n    category: 'Garage & Facility',\n  },\n  {\n    id: 'g-3',\n    src: '/images/gallery/garage_service_bay_1790239219424.jpg',\n    title: 'Multi-Brand Service Bay & Hydraulic Lifts',\n    category: 'Workshop & Repairs',\n  },\n  {\n    id: 'g-4',\n    src: '/images/gallery/hero_garage_service_1790239201662.jpg',\n    title: 'Engine & Suspension Repair Work in Action',\n    category: 'Workshop & Repairs',\n  },\n  {\n    id: 'g-5',\n    src: '/images/gallery/car_diagnostics_scan_1790239233882.jpg',\n    title: 'Computerized OBD-II Diagnostics & Error Scanning',\n    category: 'Computer Scanning',\n  },\n  {\n    id: 'g-6',\n    src: '/images/gallery/car_foam_wash_1790239251473.jpg',\n    title: 'High Pressure Foam Washing & Deep Cleaning',\n    category: 'Car Wash & Detailing',\n  },\n  {\n    id: 'g-7',\n    src: '/images/gallery/car_accessories_display_1790239267979.jpg',\n    title: 'Premium Car Accessories, Mats & Upgrades',\n    category: 'Car Accessories',\n  },\n];\n\nconst CATEGORY_META: Record<string, { hindi: string; desc: string; icon: string }> = {\n  'Garage & Facility': {\n    hindi: 'वर्कशॉप और प्रवेश द्वार',\n    desc: 'Main garage front, parking yard and office',\n    icon: '🏢',\n  },\n  'Workshop & Repairs': {\n    hindi: 'सर्विस बे और रिपेयरिंग',\n    desc: 'Hydraulic lifts, engine, brakes and suspension bay',\n    icon: '🔧',\n  },\n  'Computer Scanning': {\n    hindi: 'कंप्यूटराइज्ड स्कैनिंग',\n    desc: 'OBD-II scanner, error code checks and sensor data',\n    icon: '💻',\n  },\n  'Car Wash & Detailing': {\n    hindi: 'फोम वॉश और सफाई',\n    desc: 'High pressure foam wash, vacuum and interior cleaning',\n    icon: '🫧',\n  },\n  'Car Accessories': {\n    hindi: 'कार एक्सेसरीज व फिटिंग',\n    desc: 'Seat covers, matting, speakers, lights & fittings',\n    icon: '🚗',\n  },\n};\n\nexport const Gallery: React.FC = () => {\n  const [activePhoto, setActivePhoto] = useState<GalleryPhoto | null>(null);\n  const [userPhotos, setUserPhotos] = useState<GalleryPhoto[]>([]);\n  const [isAddModalOpen, setIsAddModalOpen] = useState(false);\n\n  // Selected folder for drill-down (null = show folders view)\n  const [selectedFolder, setSelectedFolder] = useState<string | null>(null);\n\n  // Form state\n  const [newPhotoSrc, setNewPhotoSrc] = useState('');\n  const [newPhotoTitle, setNewPhotoTitle] = useState('');\n  const [newPhotoCategory, setNewPhotoCategory] = useState('Workshop & Repairs');\n  const [photoError, setPhotoError] = useState('');\n\n  // Load user photos\n  useEffect(() => {\n    try {\n      const saved = localStorage.getItem('tiwari_motors_custom_gallery');\n      if (saved) {\n        setUserPhotos(JSON.parse(saved));\n      }\n    } catch {\n      // Ignore\n    }\n  }, []);\n\n  useEffect(() => {\n    const onKey = (e: KeyboardEvent) => {\n      if (e.key === 'Escape') {\n        if (activePhoto) setActivePhoto(null);\n        else if (selectedFolder) setSelectedFolder(null);\n      }\n    };\n    window.addEventListener('keydown', onKey);\n    return () => window.removeEventListener('keydown', onKey);\n  }, [activePhoto, selectedFolder]);\n\n  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {\n    const file = e.target.files?.[0];\n    if (!file) return;\n\n    if (!file.type.startsWith('image/')) {\n      setPhotoError('Kripya valid image chunein (JPG, PNG).');\n      return;\n    }\n\n    if (file.size > 5 * 1024 * 1024) {\n      setPhotoError('Image size 5MB se kam hona chahiye.');\n      return;\n    }\n\n    const reader = new FileReader();\n    reader.onload = () => {\n      setNewPhotoSrc(reader.result as string);\n      setPhotoError('');\n    };\n    reader.readAsDataURL(file);\n  };\n\n  const handleSavePhoto = (e: React.FormEvent) => {\n    e.preventDefault();\n    if (!newPhotoSrc) {\n      setPhotoError('Kripya photo select karein.');\n      return;\n    }\n    if (!newPhotoTitle.trim()) {\n      setPhotoError('Kripya photo ka title likhein.');\n      return;\n    }\n\n    const newItem: GalleryPhoto = {\n      id: `user-${Date.now()}`,\n      src: newPhotoSrc,\n      title: newPhotoTitle.trim(),\n      category: newPhotoCategory,\n      isUserUploaded: true,\n    };\n\n    const updated = [newItem, ...userPhotos];\n    setUserPhotos(updated);\n    try {\n      localStorage.setItem('tiwari_motors_custom_gallery', JSON.stringify(updated));\n    } catch {\n      // Ignore\n    }\n\n    // Auto navigate to that category so user sees it right away\n    setSelectedFolder(newPhotoCategory);\n\n    setNewPhotoSrc('');\n    setNewPhotoTitle('');\n    setPhotoError('');\n    setIsAddModalOpen(false);\n  };\n\n  const handleDeletePhoto = (id: string, e: React.MouseEvent) => {\n    e.stopPropagation();\n    const updated = userPhotos.filter((p) => p.id !== id);\n    setUserPhotos(updated);\n    try {\n      localStorage.setItem('tiwari_motors_custom_gallery', JSON.stringify(updated));\n    } catch {\n      // Ignore\n    }\n  };\n\n  const allItems = useMemo(() => [...userPhotos, ...DEFAULT_GALLERY], [userPhotos]);\n\n  // Group items by category to build folder cards\n  const folders = useMemo<CategoryFolder[]>(() => {\n    const map = new Map<string, GalleryPhoto[]>();\n\n    // Preset order\n    const presetCategories = [\n      'Workshop & Repairs',\n      'Computer Scanning',\n      'Car Wash & Detailing',\n      'Car Accessories',\n      'Garage & Facility',\n    ];\n\n    presetCategories.forEach((c) => map.set(c, []));\n\n    allItems.forEach((item) => {\n      const cat = item.category || 'Workshop & Repairs';\n      if (!map.has(cat)) map.set(cat, []);\n      map.get(cat)!.push(item);\n    });\n\n    const result: CategoryFolder[] = [];\n    map.forEach((photos, name) => {\n      if (photos.length > 0) {\n        const meta = CATEGORY_META[name] || {\n          hindi: name,\n          desc: `${photos.length} photos available`,\n          icon: '📁',\n        };\n        result.push({\n          name,\n          hindiTitle: meta.hindi,\n          coverImage: photos[0].src,\n          description: meta.desc,\n          iconText: meta.icon,\n        });\n      }\n    });\n\n    return result;\n  }, [allItems]);\n\n  // Photos inside the actively clicked folder\n  const currentFolderPhotos = useMemo(() => {\n    if (!selectedFolder) return [];\n    return allItems.filter((i) => i.category === selectedFolder);\n  }, [allItems, selectedFolder]);\n\n  return (\n    <section id=\"gallery\" className=\"bg-[#F8F9FA] scroll-mt-20 py-10 sm:py-14 border-b border-zinc-200\">\n      <div className=\"max-w-7xl mx-auto px-4 sm:px-6\">\n        {/* Header with Add Photo */}\n        <div className=\"flex flex-col sm:flex-row sm:items-end justify-between mb-6 gap-3\">\n          <SectionHead\n            eyebrow=\"Visual Showcase\"\n            title=\"Our Garage & Work\"\n            subtitle=\"Category par tap karke workshop ke andar ki photos dekhein.\"\n            testid=\"gallery-heading\"\n          />\n\n          <div className=\"flex items-center gap-2\">\n            <button\n              type=\"button\"\n              onClick={() => setIsAddModalOpen(true)}\n              className=\"inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-[#F58220] hover:bg-[#D96E14] text-white text-xs font-bold transition-all shadow-sm cursor-pointer\"\n            >\n              <Plus size={14} />\n              <span>Add Photo</span>\n            </button>\n            <span className=\"text-[11px] font-semibold text-zinc-500 bg-white border border-zinc-200 px-2.5 py-1 rounded-md\">\n              Total {allItems.length} Photos\n            </span>\n          </div>\n        </div>\n\n        {/* View 1: Categorized Folders (Super clean, no clutter, no huge endless page) */}\n        {!selectedFolder ? (\n          <div>\n            <div className=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3.5 sm:gap-4\">\n              {folders.map((folder) => {\n                const count = allItems.filter((p) => p.category === folder.name).length;\n                return (\n                  <div\n                    key={folder.name}\n                    onClick={() => setSelectedFolder(folder.name)}\n                    className=\"group relative rounded-xl overflow-hidden bg-white border border-zinc-200/90 shadow-2xs hover:shadow-md hover:border-[#F58220]/50 transition-all duration-300 cursor-pointer flex flex-col justify-between\"\n                  >\n                    {/* Compact Image Cover */}\n                    <div className=\"relative h-36 sm:h-40 w-full overflow-hidden bg-zinc-900\">\n                      <img\n                        src={folder.coverImage}\n                        alt={folder.name}\n                        loading=\"lazy\"\n                        onError={(e) => {\n                          (e.target as HTMLImageElement).src = GARAGE_PHOTO_SRC;\n                        }}\n                        className=\"w-full h-full object-cover group-hover:scale-105 transition-transform duration-500 brightness-90 group-hover:brightness-100\"\n                      />\n                      <div className=\"absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent\" />\n\n                      {/* Top category badge */}\n                      <div className=\"absolute top-2.5 left-2.5 flex items-center gap-1.5 px-2 py-0.5 rounded bg-black/70 backdrop-blur-xs text-white text-[11px] font-semibold\">\n                        <span>{folder.iconText}</span>\n                        <span>{folder.name}</span>\n                      </div>\n\n                      {/* Photo count */}\n                      <div className=\"absolute top-2.5 right-2.5 px-2 py-0.5 rounded bg-[#F58220] text-white text-[11px] font-bold shadow-xs\">\n                        {count} Photos\n                      </div>\n\n                      {/* Bottom title on image */}\n                      <div className=\"absolute bottom-2.5 left-3 right-3 text-white\">\n                        <p className=\"text-[11px] font-medium text-orange-200\">\n                          {folder.hindiTitle}\n                        </p>\n                        <h4 className=\"font-heading font-bold text-sm sm:text-base text-white line-clamp-1\">\n                          {folder.name}\n                        </h4>\n                      </div>\n                    </div>\n\n                    {/* Bottom action strip */}\n                    <div className=\"p-3 bg-white flex items-center justify-between border-t border-zinc-100\">\n                      <p className=\"text-[11px] text-zinc-500 line-clamp-1\">\n                        {folder.description}\n                      </p>\n                      <span className=\"inline-flex items-center gap-1 text-xs font-bold text-[#F58220] group-hover:translate-x-0.5 transition-transform shrink-0\">\n                        <span>Photos Dekhein</span>\n                        <ArrowRight size={13} />\n                      </span>\n                    </div>\n                  </div>\n                );\n              })}\n            </div>\n          </div>\n        ) : (\n          /* View 2: Inside Folder View (Clean sub-album) */\n          <div className=\"animate-in fade-in duration-200\">\n            {/* Folder Header Bar */}\n            <div className=\"bg-white rounded-xl p-3 sm:p-4 border border-zinc-200 shadow-2xs mb-5 flex flex-wrap items-center justify-between gap-3\">\n              <div className=\"flex items-center gap-2.5\">\n                <button\n                  type=\"button\"\n                  onClick={() => setSelectedFolder(null)}\n                  className=\"inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-zinc-100 hover:bg-zinc-200 text-zinc-800 text-xs font-bold transition-colors cursor-pointer\"\n                >\n                  <ArrowLeft size={14} />\n                  <span>Wapas Sabhi Categories</span>\n                </button>\n                <div className=\"h-4 w-[1px] bg-zinc-300 hidden sm:block\" />\n                <div>\n                  <h3 className=\"text-sm sm:text-base font-bold text-zinc-900 font-heading\">\n                    {selectedFolder}\n                  </h3>\n                  <p className=\"text-[11px] text-zinc-500\">\n                    {currentFolderPhotos.length} photos available in this album\n                  </p>\n                </div>\n              </div>\n\n              <span className=\"text-[11px] text-zinc-500 italic hidden md:inline\">\n                Kisi bhi photo par click karke full screen zoom dekhein\n              </span>\n            </div>\n\n            {/* Folder photos grid */}\n            <div className=\"grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-2.5 sm:gap-3.5\">\n              {currentFolderPhotos.map((item) => (\n                <div\n                  key={item.id}\n                  onClick={() => setActivePhoto(item)}\n                  className=\"group relative rounded-xl overflow-hidden border border-zinc-200 bg-white shadow-2xs hover:shadow-md transition-all duration-300 cursor-pointer aspect-[4/3]\"\n                >\n                  <img\n                    src={item.src}\n                    alt={item.title}\n                    loading=\"lazy\"\n                    onError={(e) => {\n                      (e.target as HTMLImageElement).src = GARAGE_PHOTO_SRC;\n                    }}\n                    className=\"w-full h-full object-cover group-hover:scale-105 transition-transform duration-500\"\n                  />\n\n                  <div className=\"absolute inset-0 bg-gradient-to-t from-black/80 via-black/10 to-transparent opacity-0 group-hover:opacity-100 transition-opacity flex flex-col justify-between p-2.5 text-white\">\n                    <div className=\"flex justify-end\">\n                      <div className=\"p-1 rounded bg-white/20 backdrop-blur-xs text-white\">\n                        <ZoomIn size={13} />\n                      </div>\n                    </div>\n                    <p className=\"text-xs font-bold font-heading line-clamp-2\">\n                      {item.title}\n                    </p>\n                  </div>\n\n                  {item.isUserUploaded && (\n                    <button\n                      type=\"button\"\n                      onClick={(e) => handleDeletePhoto(item.id, e)}\n                      className=\"absolute top-2 right-2 p-1.5 bg-black/75 hover:bg-red-600 text-white rounded-md transition-colors z-20\"\n                      title=\"Delete Photo\"\n                    >\n                      <Trash2 size={12} />\n                    </button>\n                  )}\n                </div>\n              ))}\n            </div>\n          </div>\n        )}\n      </div>\n\n      {/* Add Photo Modal */}\n      {isAddModalOpen && (\n        <div\n          role=\"dialog\"\n          aria-modal=\"true\"\n          className=\"fixed inset-0 z-50 bg-black/80 backdrop-blur-xs flex items-center justify-center p-4 animate-in fade-in duration-150\"\n          onClick={() => setIsAddModalOpen(false)}\n        >\n          <div\n            className=\"relative max-w-md w-full bg-white rounded-2xl overflow-hidden shadow-2xl border border-zinc-200 p-5\"\n            onClick={(e) => e.stopPropagation()}\n          >\n            <div className=\"flex items-center justify-between pb-3 border-b border-zinc-200 mb-3.5\">\n              <div className=\"flex items-center gap-2\">\n                <div className=\"w-8 h-8 rounded-lg bg-orange-100 flex items-center justify-center text-[#F58220]\">\n                  <ImagePlus size={18} />\n                </div>\n                <h3 className=\"text-base font-bold text-zinc-900 font-heading\">\n                  Nayi Photo Upload Karein\n                </h3>\n              </div>\n              <button\n                type=\"button\"\n                onClick={() => setIsAddModalOpen(false)}\n                className=\"p-1 rounded-md text-zinc-400 hover:text-zinc-700 transition-colors cursor-pointer\"\n              >\n                <X size={18} />\n              </button>\n            </div>\n\n            {photoError && (\n              <div className=\"mb-3 p-2 rounded bg-red-50 text-red-700 text-xs border border-red-200\">\n                {photoError}\n              </div>\n            )}\n\n            <form onSubmit={handleSavePhoto} className=\"space-y-3\">\n              <div>\n                <label className=\"block text-xs font-semibold text-zinc-700 mb-1\">\n                  Photo Select Karein\n                </label>\n                <input\n                  type=\"file\"\n                  accept=\"image/*\"\n                  onChange={handleFileUpload}\n                  className=\"w-full text-xs text-zinc-600 file:mr-3 file:py-1.5 file:px-3 file:rounded-md file:border-0 file:text-xs file:font-semibold file:bg-orange-50 file:text-[#F58220] hover:file:bg-orange-100 cursor-pointer\"\n                />\n              </div>\n\n              {newPhotoSrc && (\n                <div className=\"relative rounded-lg overflow-hidden h-28 bg-zinc-100 border border-zinc-200\">\n                  <img\n                    src={newPhotoSrc}\n                    alt=\"Preview\"\n                    className=\"w-full h-full object-cover\"\n                  />\n                </div>\n              )}\n\n              <div>\n                <label className=\"block text-xs font-semibold text-zinc-700 mb-1\">\n                  Photo Title <span className=\"text-[#F58220]\">*</span>\n                </label>\n                <input\n                  type=\"text\"\n                  required\n                  value={newPhotoTitle}\n                  onChange={(e) => setNewPhotoTitle(e.target.value)}\n                  placeholder=\"e.g. Scorpio Service, New Bay, Scanner\"\n                  className=\"w-full bg-zinc-50 border border-zinc-300 rounded-lg px-3 py-1.5 text-xs text-zinc-900 focus:outline-none focus:border-[#F58220]\"\n                />\n              </div>\n\n              <div>\n                <label className=\"block text-xs font-semibold text-zinc-700 mb-1\">\n                  Kaun Si Category (Folder) Me Daalna Hai?\n                </label>\n                <select\n                  value={newPhotoCategory}\n                  onChange={(e) => setNewPhotoCategory(e.target.value)}\n                  className=\"w-full bg-zinc-50 border border-zinc-300 rounded-lg px-3 py-1.5 text-xs text-zinc-900 focus:outline-none focus:border-[#F58220]\"\n                >\n                  <option value=\"Workshop & Repairs\">Workshop & Repairs</option>\n                  <option value=\"Computer Scanning\">Computer Scanning</option>\n                  <option value=\"Car Wash & Detailing\">Car Wash & Detailing</option>\n                  <option value=\"Car Accessories\">Car Accessories</option>\n                  <option value=\"Garage & Facility\">Garage & Facility</option>\n                </select>\n              </div>\n\n              <div className=\"pt-2 flex items-center justify-end gap-2\">\n                <button\n                  type=\"button\"\n                  onClick={() => setIsAddModalOpen(false)}\n                  className=\"px-3 py-1.5 text-xs font-semibold text-zinc-600 hover:text-zinc-900\"\n                >\n                  Cancel\n                </button>\n                <button\n                  type=\"submit\"\n                  className=\"px-4 py-1.5 rounded-lg bg-[#F58220] hover:bg-[#D96E14] text-white text-xs font-bold shadow-xs\"\n                >\n                  Photo Save Karein\n                </button>\n              </div>\n            </form>\n          </div>\n        </div>\n      )}\n\n      {/* Lightbox Modal */}\n      {activePhoto && (\n        <div\n          role=\"dialog\"\n          aria-modal=\"true\"\n          className=\"fixed inset-0 z-50 bg-black/90 backdrop-blur-xs flex items-center justify-center p-4 animate-in fade-in duration-150\"\n          onClick={() => setActivePhoto(null)}\n        >\n          <div\n            className=\"relative max-w-4xl w-full bg-[#1c1c1c] rounded-2xl overflow-hidden border border-zinc-700 shadow-2xl\"\n            onClick={(e) => e.stopPropagation()}\n          >\n            <div className=\"relative max-h-[75vh] flex items-center justify-center bg-black\">\n              <img\n                src={activePhoto.src}\n                alt={activePhoto.title}\n                className=\"max-h-[75vh] w-auto max-w-full object-contain\"\n              />\n              <button\n                type=\"button\"\n                onClick={() => setActivePhoto(null)}\n                className=\"absolute top-3 right-3 p-1.5 rounded-full bg-black/60 hover:bg-black text-white hover:text-[#F58220] transition-colors cursor-pointer\"\n                aria-label=\"Close\"\n              >\n                <X size={20} />\n              </button>\n            </div>\n            <div className=\"p-3 bg-[#181818] border-t border-zinc-800 flex items-center justify-between gap-3\">\n              <div>\n                <span className=\"text-[10px] font-bold uppercase tracking-wider text-[#F58220]\">\n                  {activePhoto.category}\n                </span>\n                <p className=\"text-sm font-bold text-white font-heading mt-0.5\">\n                  {activePhoto.title}\n                </p>\n              </div>\n              <button\n                type=\"button\"\n                onClick={() => setActivePhoto(null)}\n                className=\"px-3 py-1.5 text-xs font-semibold bg-zinc-800 hover:bg-zinc-700 text-white rounded-lg transition-colors cursor-pointer\"\n              >\n                Close\n              </button>\n            </div>\n          </div>\n        </div>\n      )}\n    </section>\n  );\n};\n",
  "src/components/Reviews.tsx": "import React from 'react';\nimport { Star, Quote, ExternalLink } from 'lucide-react';\nimport { Reveal, SectionHead } from './Reveal';\nimport { BUSINESS } from '../config';\n\nexport const Reviews: React.FC = () => {\n  return (\n    <section id=\"reviews\" className=\"bg-[#F7F7F7] scroll-mt-20 py-14 sm:py-20 border-b border-zinc-200\">\n      <div className=\"max-w-7xl mx-auto px-4 sm:px-6\">\n        <SectionHead\n          eyebrow=\"Reviews\"\n          title=\"What Our Customers Say\"\n          subtitle=\"Aapka feedback hi hamari asli pehchaan hai.\"\n          testid=\"reviews-heading\"\n        />\n\n        <Reveal delay={0.12} className=\"mt-9\">\n          <div className=\"max-w-2xl mx-auto bg-white border border-zinc-200 rounded-2xl p-8 text-center shadow-sm\">\n            <span className=\"mx-auto flex items-center justify-center w-12 h-12 rounded-full bg-[#F58220]/10 mb-4\">\n              <Quote size={22} className=\"text-[#F58220]\" />\n            </span>\n\n            {/* Stars */}\n            <div className=\"flex items-center justify-center gap-1 text-[#F58220] mb-4\">\n              {[...Array(5)].map((_, i) => (\n                <Star key={i} size={18} className=\"fill-current text-[#F58220]\" />\n              ))}\n            </div>\n\n            <p className=\"text-sm sm:text-base text-zinc-700 italic leading-relaxed\">\n              “Bohot badhiya service! Car ki engine aur electrical problem thi, Tiwari Motors pe time par aur reasonable rate me solve ho gaya. Ambedkar Nagar me trustworthy smart garage hai.”\n            </p>\n\n            <p className=\"mt-4 font-heading font-semibold text-xs text-zinc-900 uppercase tracking-wider\">\n              — Verified Car Owner, Ambedkar Nagar\n            </p>\n\n            <div className=\"mt-6 pt-6 border-t border-zinc-100 flex items-center justify-center\">\n              <a\n                href={BUSINESS.googleReviewUrl}\n                target=\"_blank\"\n                rel=\"noreferrer\"\n                data-testid=\"google-review-link\"\n                className=\"inline-flex items-center gap-1.5 text-xs font-bold text-[#F58220] hover:text-[#D96E14] transition-colors\"\n              >\n                <span>Write a Review on Google</span>\n                <ExternalLink size={13} />\n              </a>\n            </div>\n          </div>\n        </Reveal>\n      </div>\n    </section>\n  );\n};\n",
  "src/components/Booking.tsx": "import React, { useState, useEffect } from 'react';\nimport { Phone, MessageCircle, Send, CheckCircle2, Clock, Calendar } from 'lucide-react';\nimport { Reveal, SectionHead } from './Reveal';\nimport { SERVICES, waLink } from '../config';\nimport { useOwner } from '../context/OwnerContext';\n\ninterface BookingProps {\n  selectedService?: string;\n}\n\nexport const Booking: React.FC<BookingProps> = ({ selectedService }) => {\n  const { business } = useOwner();\n  const [form, setForm] = useState({\n    name: '',\n    mobile: '',\n    car: '',\n    service: '',\n    date: '',\n    message: '',\n  });\n\n  const [errors, setErrors] = useState<Record<string, string | undefined>>({});\n  const [sent, setSent] = useState(false);\n\n  useEffect(() => {\n    if (selectedService) {\n      setForm((f) => ({ ...f, service: selectedService }));\n    }\n  }, [selectedService]);\n\n  const set = (k: string) => (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {\n    setForm((f) => ({ ...f, [k]: e.target.value }));\n    setErrors((er) => ({ ...er, [k]: undefined }));\n  };\n\n  const submit = (e: React.FormEvent) => {\n    e.preventDefault();\n    const errs: Record<string, string> = {};\n    if (!form.name.trim()) errs.name = 'Apna naam likhiye';\n    const digits = form.mobile.replace(/\\D/g, '').replace(/^91(?=\\d{10}$)/, '');\n    if (!/^[6-9]\\d{9}$/.test(digits)) {\n      errs.mobile = 'Sahi 10-digit mobile number daaliye';\n    }\n    if (!form.service) errs.service = 'Service chuniye';\n\n    setErrors(errs);\n    if (Object.keys(errs).length) return;\n\n    const msg = [\n      '🚗 *New Service Request - Tiwari Motors*',\n      '',\n      `👤 *Name:* ${form.name.trim()}`,\n      `📱 *Mobile:* ${digits}`,\n      `🚘 *Car:* ${form.car.trim() || 'Not specified'}`,\n      `🔧 *Service:* ${form.service}`,\n      `📅 *Preferred Date:* ${form.date || 'Earliest available'}`,\n      `📝 *Issue Details:* ${form.message.trim() || 'General service'}`,\n    ].join('\\n');\n\n    window.open(waLink(msg), '_blank', 'noopener');\n    setSent(true);\n  };\n\n  const today = new Date().toISOString().split('T')[0];\n\n  return (\n    <section id=\"booking\" className=\"bg-white scroll-mt-20 py-14 sm:py-20 border-b border-zinc-200\">\n      <div className=\"max-w-7xl mx-auto px-4 sm:px-6 grid lg:grid-cols-[0.9fr_1.1fr] gap-10 items-start\">\n        {/* Left Column: Details */}\n        <div>\n          <SectionHead\n            eyebrow=\"Book Now\"\n            title=\"Book Your Car Service\"\n            testid=\"booking-heading\"\n          />\n\n          <Reveal delay={0.1}>\n            <p className=\"mt-4 text-sm sm:text-base text-zinc-600 leading-relaxed\">\n              Form bhariye — aapki request seedhe WhatsApp par hamare paas aayegi. Ya seedha call kijiye, hum turant madad karenge.\n            </p>\n\n            <div className=\"mt-6 p-4 rounded-2xl bg-[#F7F7F7] border border-zinc-200 space-y-3\">\n              <div className=\"flex items-center gap-2.5 text-xs text-zinc-700\">\n                <Clock size={16} className=\"text-[#F58220] shrink-0\" />\n                <span>\n                  <strong className=\"text-zinc-900 font-semibold\">Workshop Timings:</strong> {business.hours}\n                </span>\n              </div>\n              <div className=\"flex items-center gap-2.5 text-xs text-zinc-700\">\n                <Calendar size={16} className=\"text-[#F58220] shrink-0\" />\n                <span>Same-day inspection & transparent estimates</span>\n              </div>\n            </div>\n\n            <div className=\"mt-6 flex flex-col sm:flex-row gap-3\">\n              <a\n                href={`tel:${business.phonePrimaryIntl}`}\n                className=\"inline-flex items-center justify-center gap-2 px-5 py-3 rounded-xl bg-[#111111] hover:bg-black text-white text-xs sm:text-sm font-semibold transition-colors\"\n              >\n                <Phone size={15} className=\"text-[#F58220]\" />\n                <span>Call: {business.phonePrimary}</span>\n              </a>\n\n              <a\n                href={waLink('Namaste Tiwari Motors, I would like to book a service.')}\n                target=\"_blank\"\n                rel=\"noreferrer\"\n                className=\"inline-flex items-center justify-center gap-2 px-5 py-3 rounded-xl bg-[#25D366] hover:bg-[#1fb857] text-white text-xs sm:text-sm font-semibold transition-colors shadow-sm\"\n              >\n                <MessageCircle size={17} />\n                <span>Chat on WhatsApp</span>\n              </a>\n            </div>\n          </Reveal>\n        </div>\n\n        {/* Right Column: Form */}\n        <Reveal delay={0.15}>\n          <div className=\"bg-[#F7F7F7] border border-zinc-200 rounded-3xl p-6 sm:p-8 shadow-sm\">\n            {sent ? (\n              <div className=\"text-center py-10 space-y-3\" data-testid=\"booking-success-message\">\n                <div className=\"w-12 h-12 rounded-full bg-emerald-100 text-emerald-600 mx-auto flex items-center justify-center\">\n                  <CheckCircle2 size={24} />\n                </div>\n                <h3 className=\"text-lg font-bold text-zinc-900 font-heading\">\n                  Request Sent on WhatsApp!\n                </h3>\n                <p className=\"text-xs sm:text-sm text-zinc-600 max-w-sm mx-auto\">\n                  Shukriya! Tiwari Motors team aapse turant contact karegi. Agar urgent hai toh aap seedha call bhi kar sakte hain.\n                </p>\n                <button\n                  type=\"button\"\n                  onClick={() => setSent(false)}\n                  className=\"mt-4 text-xs font-bold text-[#F58220] hover:underline\"\n                >\n                  Naya request bhejein\n                </button>\n              </div>\n            ) : (\n              <form onSubmit={submit} className=\"space-y-4\" data-testid=\"booking-form\">\n                <div className=\"grid sm:grid-cols-2 gap-4\">\n                  {/* Name */}\n                  <div>\n                    <label className=\"block text-xs font-bold text-zinc-700 uppercase tracking-wider mb-1 font-heading\">\n                      Aapka Naam <span className=\"text-[#F58220]\">*</span>\n                    </label>\n                    <input\n                      type=\"text\"\n                      required\n                      value={form.name}\n                      onChange={set('name')}\n                      placeholder=\"e.g. Rahul Sharma\"\n                      className={`w-full bg-white border ${\n                        errors.name ? 'border-red-500' : 'border-zinc-300'\n                      } rounded-xl px-3.5 py-2.5 text-xs sm:text-sm text-zinc-900 focus:outline-none focus:border-[#F58220] transition-colors`}\n                    />\n                    {errors.name && (\n                      <span className=\"text-[11px] text-red-500 mt-1 block\">\n                        {errors.name}\n                      </span>\n                    )}\n                  </div>\n\n                  {/* Mobile */}\n                  <div>\n                    <label className=\"block text-xs font-bold text-zinc-700 uppercase tracking-wider mb-1 font-heading\">\n                      Mobile Number <span className=\"text-[#F58220]\">*</span>\n                    </label>\n                    <input\n                      type=\"tel\"\n                      required\n                      value={form.mobile}\n                      onChange={set('mobile')}\n                      placeholder=\"10-digit number\"\n                      className={`w-full bg-white border ${\n                        errors.mobile ? 'border-red-500' : 'border-zinc-300'\n                      } rounded-xl px-3.5 py-2.5 text-xs sm:text-sm text-zinc-900 focus:outline-none focus:border-[#F58220] transition-colors`}\n                    />\n                    {errors.mobile && (\n                      <span className=\"text-[11px] text-red-500 mt-1 block\">\n                        {errors.mobile}\n                      </span>\n                    )}\n                  </div>\n                </div>\n\n                <div className=\"grid sm:grid-cols-2 gap-4\">\n                  {/* Car */}\n                  <div>\n                    <label className=\"block text-xs font-bold text-zinc-700 uppercase tracking-wider mb-1 font-heading\">\n                      Car Model / Make\n                    </label>\n                    <input\n                      type=\"text\"\n                      value={form.car}\n                      onChange={set('car')}\n                      placeholder=\"e.g. Swift, Creta, Scorpio\"\n                      className=\"w-full bg-white border border-zinc-300 rounded-xl px-3.5 py-2.5 text-xs sm:text-sm text-zinc-900 focus:outline-none focus:border-[#F58220] transition-colors\"\n                    />\n                  </div>\n\n                  {/* Service */}\n                  <div>\n                    <label className=\"block text-xs font-bold text-zinc-700 uppercase tracking-wider mb-1 font-heading\">\n                      Service Required <span className=\"text-[#F58220]\">*</span>\n                    </label>\n                    <select\n                      value={form.service}\n                      onChange={set('service')}\n                      className={`w-full bg-white border ${\n                        errors.service ? 'border-red-500' : 'border-zinc-300'\n                      } rounded-xl px-3.5 py-2.5 text-xs sm:text-sm text-zinc-900 focus:outline-none focus:border-[#F58220] transition-colors`}\n                    >\n                      <option value=\"\">-- Service Chuniye --</option>\n                      {SERVICES.map((s) => (\n                        <option key={s.id} value={s.name}>\n                          {s.name}\n                        </option>\n                      ))}\n                      <option value=\"General Checkup / Other\">General Checkup / Other</option>\n                    </select>\n                    {errors.service && (\n                      <span className=\"text-[11px] text-red-500 mt-1 block\">\n                        {errors.service}\n                      </span>\n                    )}\n                  </div>\n                </div>\n\n                {/* Date */}\n                <div>\n                  <label className=\"block text-xs font-bold text-zinc-700 uppercase tracking-wider mb-1 font-heading\">\n                    Preferred Date\n                  </label>\n                  <input\n                    type=\"date\"\n                    min={today}\n                    value={form.date}\n                    onChange={set('date')}\n                    className=\"w-full bg-white border border-zinc-300 rounded-xl px-3.5 py-2.5 text-xs sm:text-sm text-zinc-900 focus:outline-none focus:border-[#F58220] transition-colors\"\n                  />\n                </div>\n\n                {/* Message */}\n                <div>\n                  <label className=\"block text-xs font-bold text-zinc-700 uppercase tracking-wider mb-1 font-heading\">\n                    Problem ya Requirement details\n                  </label>\n                  <textarea\n                    rows={3}\n                    value={form.message}\n                    onChange={set('message')}\n                    placeholder=\"e.g. Engine light on, AC not cooling, 50k km regular servicing...\"\n                    className=\"w-full bg-white border border-zinc-300 rounded-xl px-3.5 py-2 text-xs sm:text-sm text-zinc-900 focus:outline-none focus:border-[#F58220] transition-colors resize-none\"\n                  />\n                </div>\n\n                <button\n                  type=\"submit\"\n                  data-testid=\"booking-submit-btn\"\n                  className=\"w-full inline-flex items-center justify-center gap-2 py-3 rounded-xl bg-[#F58220] hover:bg-[#D96E14] text-white text-sm font-bold shadow-md transition-all hover:shadow-lg cursor-pointer\"\n                >\n                  <Send size={16} />\n                  <span>Send Request on WhatsApp</span>\n                </button>\n              </form>\n            )}\n          </div>\n        </Reveal>\n      </div>\n    </section>\n  );\n};\n",
  "src/components/Contact.tsx": "import React from 'react';\nimport { MapPin, Phone, Mail, Clock, Navigation } from 'lucide-react';\nimport { SectionHead } from './Reveal';\nimport { MAPS } from '../config';\nimport { useOwner } from '../context/OwnerContext';\n\nexport const Contact: React.FC = () => {\n  const { business } = useOwner();\n\n  return (\n    <section id=\"contact\" className=\"bg-[#F8F9FA] scroll-mt-20 py-8 sm:py-12 border-b border-zinc-200\">\n      <div className=\"max-w-7xl mx-auto px-4 sm:px-6\">\n        <SectionHead\n          eyebrow=\"Location & Contact\"\n          title=\"Visit Tiwari Motors Smart Garage\"\n          subtitle=\"Direct phone karein, WhatsApp karein ya seedhe workshop par visit karein.\"\n          testid=\"contact-heading\"\n        />\n\n        <div className=\"mt-6 grid lg:grid-cols-12 gap-4 items-stretch\">\n          {/* Information Card (5 Columns on Desktop) - Compact & Clean */}\n          <div className=\"lg:col-span-5 bg-white border border-zinc-200/90 rounded-2xl p-4 sm:p-5 shadow-2xs flex flex-col justify-between space-y-4\">\n            <div className=\"space-y-3.5\">\n              {/* Address */}\n              <div className=\"flex items-start gap-2.5\">\n                <span className=\"flex items-center justify-center w-8 h-8 rounded-lg bg-[#F58220]/10 shrink-0 text-[#F58220] mt-0.5\">\n                  <MapPin size={16} />\n                </span>\n                <div className=\"min-w-0\">\n                  <p className=\"font-heading font-bold text-[10px] text-zinc-400 uppercase tracking-wider\">\n                    Workshop Address\n                  </p>\n                  <p className=\"mt-0.5 text-xs sm:text-sm font-bold text-zinc-900 leading-snug\">\n                    {business.address}\n                  </p>\n                </div>\n              </div>\n\n              {/* Phone */}\n              <div className=\"flex items-start gap-2.5\">\n                <span className=\"flex items-center justify-center w-8 h-8 rounded-lg bg-[#F58220]/10 shrink-0 text-[#F58220] mt-0.5\">\n                  <Phone size={16} />\n                </span>\n                <div className=\"min-w-0\">\n                  <p className=\"font-heading font-bold text-[10px] text-zinc-400 uppercase tracking-wider\">\n                    Phone Numbers\n                  </p>\n                  <div className=\"mt-0.5 flex flex-wrap gap-x-2 gap-y-1 text-xs sm:text-sm font-bold text-zinc-900\">\n                    <a\n                      href={`tel:${business.phonePrimaryIntl}`}\n                      className=\"hover:text-[#F58220] transition-colors\"\n                    >\n                      +91 {business.phonePrimary}\n                    </a>\n                    {business.phoneSecondary && (\n                      <>\n                        <span className=\"text-zinc-300\">/</span>\n                        <a\n                          href={`tel:${business.phoneSecondaryIntl}`}\n                          className=\"hover:text-[#F58220] transition-colors\"\n                        >\n                          +91 {business.phoneSecondary}\n                        </a>\n                      </>\n                    )}\n                  </div>\n                </div>\n              </div>\n\n              {/* Timings & Email Inline */}\n              <div className=\"grid grid-cols-2 gap-2 pt-1\">\n                <div className=\"flex items-start gap-2\">\n                  <span className=\"flex items-center justify-center w-7 h-7 rounded-md bg-[#F58220]/10 shrink-0 text-[#F58220] mt-0.5\">\n                    <Clock size={14} />\n                  </span>\n                  <div>\n                    <p className=\"font-heading font-bold text-[10px] text-zinc-400 uppercase tracking-wider\">\n                      Timings\n                    </p>\n                    <p className=\"mt-0.5 text-xs font-semibold text-zinc-900 leading-tight\">\n                      {business.hours}\n                    </p>\n                  </div>\n                </div>\n\n                <div className=\"flex items-start gap-2\">\n                  <span className=\"flex items-center justify-center w-7 h-7 rounded-md bg-[#F58220]/10 shrink-0 text-[#F58220] mt-0.5\">\n                    <Mail size={14} />\n                  </span>\n                  <div className=\"min-w-0\">\n                    <p className=\"font-heading font-bold text-[10px] text-zinc-400 uppercase tracking-wider\">\n                      Email\n                    </p>\n                    <p className=\"mt-0.5 text-xs font-semibold text-zinc-800 truncate\">\n                      {business.email}\n                    </p>\n                  </div>\n                </div>\n              </div>\n            </div>\n\n            {/* Direction button */}\n            <div className=\"pt-2 border-t border-zinc-100\">\n              <a\n                href={MAPS.directionsUrl}\n                target=\"_blank\"\n                rel=\"noreferrer\"\n                data-testid=\"contact-directions-btn\"\n                className=\"w-full inline-flex items-center justify-center gap-1.5 px-4 py-2.5 rounded-xl bg-[#F58220] hover:bg-[#D96E14] text-white font-bold text-xs shadow-xs transition-all\"\n              >\n                <Navigation size={14} />\n                <span>Open Google Maps Directions</span>\n              </a>\n            </div>\n          </div>\n\n          {/* Map Embed Card (7 Columns on Desktop) - Compact Height */}\n          <div className=\"lg:col-span-7 rounded-2xl overflow-hidden border border-zinc-200 shadow-2xs bg-zinc-200 h-56 sm:h-64 lg:h-auto min-h-[220px]\">\n            <iframe\n              title=\"Tiwari Motors Smart Garage Location Map\"\n              src={MAPS.embedUrl}\n              className=\"w-full h-full min-h-[220px] border-0\"\n              loading=\"lazy\"\n              referrerPolicy=\"no-referrer-when-downgrade\"\n            />\n          </div>\n        </div>\n      </div>\n    </section>\n  );\n};\n",
  "src/components/Footer.tsx": "import React from 'react';\nimport { Phone, Mail, MapPin, Clock, Settings } from 'lucide-react';\nimport { LOGO_SRC, SERVICES, scrollToSection } from '../config';\nimport { useOwner } from '../context/OwnerContext';\n\nconst QUICK_LINKS = [\n  { id: 'home', label: 'Home' },\n  { id: 'services', label: 'Services' },\n  { id: 'about', label: 'About Us' },\n  { id: 'gallery', label: 'Gallery' },\n  { id: 'reviews', label: 'Reviews' },\n  { id: 'booking', label: 'Book Service' },\n  { id: 'contact', label: 'Contact' },\n];\n\ninterface FooterProps {\n  onSelectService: (serviceName: string) => void;\n}\n\nexport const Footer: React.FC<FooterProps> = ({ onSelectService }) => {\n  const { business, setIsEditModalOpen } = useOwner();\n\n  const go = (e: React.MouseEvent, id: string) => {\n    e.preventDefault();\n    scrollToSection(id);\n  };\n\n  return (\n    <footer className=\"bg-[#0c0c0c] text-zinc-400 border-t border-white/10\" data-testid=\"site-footer\">\n      <div className=\"max-w-7xl mx-auto px-4 sm:px-6 py-12 lg:py-16 grid gap-10 sm:grid-cols-2 lg:grid-cols-4\">\n        {/* Col 1: Brand */}\n        <div className=\"space-y-4\">\n          <div className=\"flex items-center gap-2.5\">\n            <img\n              src={LOGO_SRC}\n              alt=\"Tiwari Motors logo\"\n              className=\"h-10 w-10 rounded-md bg-white object-cover\"\n            />\n            <span className=\"leading-tight\">\n              <span className=\"block font-heading font-bold text-white text-base\">\n                Tiwari Motors\n              </span>\n              <span className=\"block text-[10px] tracking-[0.28em] text-[#F58220] font-semibold\">\n                SMART GARAGE\n              </span>\n            </span>\n          </div>\n          <p className=\"text-sm text-zinc-400 italic\">\n            “{business.tagline}”\n          </p>\n          <p className=\"text-xs text-zinc-500\">\n            Multi-brand automobile service, repair and car care workshop located at Ambedkar Nagar, Uttar Pradesh.\n          </p>\n          <div className=\"pt-1\">\n            <button\n              type=\"button\"\n              onClick={() => setIsEditModalOpen(true)}\n              className=\"inline-flex items-center gap-1.5 text-xs text-zinc-500 hover:text-[#F58220] transition-colors cursor-pointer\"\n            >\n              <Settings size={13} />\n              <span>Owner Control Panel</span>\n            </button>\n          </div>\n        </div>\n\n        {/* Col 2: Quick Links */}\n        <div>\n          <h4 className=\"font-heading font-bold text-sm text-white uppercase tracking-wider mb-4\">\n            Quick Navigation\n          </h4>\n          <ul className=\"space-y-2.5 text-xs sm:text-sm\">\n            {QUICK_LINKS.map((link) => (\n              <li key={link.id}>\n                <a\n                  href={`#${link.id}`}\n                  onClick={(e) => go(e, link.id)}\n                  className=\"hover:text-[#F58220] transition-colors\"\n                >\n                  {link.label}\n                </a>\n              </li>\n            ))}\n          </ul>\n        </div>\n\n        {/* Col 3: Services */}\n        <div>\n          <h4 className=\"font-heading font-bold text-sm text-white uppercase tracking-wider mb-4\">\n            Our Services\n          </h4>\n          <ul className=\"space-y-2.5 text-xs sm:text-sm\">\n            {SERVICES.slice(0, 6).map((s) => (\n              <li key={s.id}>\n                <button\n                  type=\"button\"\n                  onClick={() => {\n                    onSelectService(s.name);\n                    scrollToSection('booking');\n                  }}\n                  className=\"hover:text-[#F58220] transition-colors text-left cursor-pointer\"\n                >\n                  {s.name}\n                </button>\n              </li>\n            ))}\n          </ul>\n        </div>\n\n        {/* Col 4: Contact & Hours */}\n        <div className=\"space-y-3.5 text-xs sm:text-sm\">\n          <h4 className=\"font-heading font-bold text-sm text-white uppercase tracking-wider mb-4\">\n            Workshop Info\n          </h4>\n          <div className=\"flex items-start gap-2.5\">\n            <MapPin size={15} className=\"text-[#F58220] mt-0.5 shrink-0\" />\n            <span>{business.address}</span>\n          </div>\n          <div className=\"flex items-center gap-2.5\">\n            <Clock size={15} className=\"text-[#F58220] shrink-0\" />\n            <span>{business.hours}</span>\n          </div>\n          <div className=\"flex items-center gap-2.5\">\n            <Phone size={15} className=\"text-[#F58220] shrink-0\" />\n            <a href={`tel:${business.phonePrimaryIntl}`} className=\"hover:text-white\">\n              +91 {business.phonePrimary}\n            </a>\n          </div>\n          <div className=\"flex items-center gap-2.5\">\n            <Mail size={15} className=\"text-[#F58220] shrink-0\" />\n            <span>{business.email}</span>\n          </div>\n        </div>\n      </div>\n\n      <div className=\"border-t border-white/5 py-6\">\n        <div className=\"max-w-7xl mx-auto px-4 sm:px-6 flex flex-col sm:flex-row items-center justify-between gap-3 text-xs text-zinc-500\">\n          <p>© {new Date().getFullYear()} Tiwari Motors Smart Garage. All rights reserved.</p>\n          <p className=\"flex items-center gap-1.5\">\n            <span>Ambedkar Nagar, Uttar Pradesh</span>\n            <span>•</span>\n            <span className=\"text-zinc-400\">Aapki Gadi, Hamari Zimmedari.</span>\n          </p>\n        </div>\n      </div>\n    </footer>\n  );\n};\n",
  "package.json": "{\n  \"name\": \"react-example\",\n  \"private\": true,\n  \"version\": \"0.0.0\",\n  \"type\": \"module\",\n  \"scripts\": {\n    \"dev\": \"vite --port=3000 --host=0.0.0.0\",\n    \"build\": \"vite build\",\n    \"preview\": \"vite preview\",\n    \"clean\": \"rm -rf dist server.js\",\n    \"lint\": \"tsc --noEmit\"\n  },\n  \"dependencies\": {\n    \"@google/genai\": \"^2.4.0\",\n    \"@tailwindcss/vite\": \"^4.3.3\",\n    \"@vitejs/plugin-react\": \"^6.1.1\",\n    \"dotenv\": \"^17.2.3\",\n    \"express\": \"^4.21.2\",\n    \"framer-motion\": \"^13.4.2\",\n    \"lucide-react\": \"^0.546.0\",\n    \"motion\": \"^12.23.24\",\n    \"react\": \"^19.0.1\",\n    \"react-dom\": \"^19.0.1\",\n    \"vite\": \"^8.3.0\"\n  },\n  \"devDependencies\": {\n    \"@types/node\": \"^22.14.0\",\n    \"@types/react\": \"^19.3.0\",\n    \"@types/react-dom\": \"^19.3.0\",\n    \"autoprefixer\": \"^10.4.21\",\n    \"esbuild\": \"^0.25.0\",\n    \"tailwindcss\": \"^4.3.3\",\n    \"tsx\": \"^4.21.0\",\n    \"typescript\": \"^7.0.2\",\n    \"@types/express\": \"^4.17.21\"\n  }\n}\n",
  "index.html": "<!doctype html>\n<html lang=\"en\" class=\"scroll-smooth\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <title>Tiwari Motors Smart Garage | Car Service & Repair in Ambedkar Nagar</title>\n    <meta\n      name=\"description\"\n      content=\"Tiwari Motors Smart Garage in Ambedkar Nagar provides multi-brand car service, repair, engine work, electrical, AC repair, computer scanning, washing, denting & painting, wheel alignment and car accessories.\"\n    />\n    <meta property=\"og:type\" content=\"website\" />\n    <meta property=\"og:title\" content=\"Tiwari Motors Smart Garage | Car Service & Repair in Ambedkar Nagar\" />\n    <meta\n      property=\"og:description\"\n      content=\"Multi-brand automobile service & repair in Ambedkar Nagar. Routine servicing, engine work, electrical, AC repair, computer scanning, denting & painting, foam wash, wheel alignment and accessories.\"\n    />\n    <meta property=\"og:site_name\" content=\"Tiwari Motors Smart Garage\" />\n    <meta name=\"twitter:card\" content=\"summary_large_image\" />\n    <meta name=\"twitter:title\" content=\"Tiwari Motors Smart Garage | Car Service & Repair in Ambedkar Nagar\" />\n    <meta\n      name=\"twitter:description\"\n      content=\"Multi-brand automobile service & repair in Ambedkar Nagar. Aapki Car Ki Har Zarurat Ka Ek Hi Naam.\"\n    />\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\n    <link\n      href=\"https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=Poppins:wght@400;500;600;700;800&display=swap\"\n      rel=\"stylesheet\"\n    />\n    <script type=\"application/ld+json\">\n    {\n      \"@context\": \"https://schema.org\",\n      \"@type\": \"AutoRepair\",\n      \"name\": \"Tiwari Motors Smart Garage\",\n      \"alternateName\": \"तिवारी मोटर्स\",\n      \"description\": \"Multi-brand car service, repair, engine, electrical, AC, computer scanning, washing, denting & painting, wheel alignment and car accessories.\",\n      \"telephone\": \"+918218766134\",\n      \"email\": \"tiwarimotors25@gmail.com\",\n      \"address\": {\n        \"@type\": \"PostalAddress\",\n        \"streetAddress\": \"Hussenpur Khurd Chowk\",\n        \"addressLocality\": \"Ambedkar Nagar\",\n        \"addressRegion\": \"Uttar Pradesh\",\n        \"postalCode\": \"224181\",\n        \"addressCountry\": \"IN\"\n      },\n      \"priceRange\": \"$$\",\n      \"openingHours\": \"Mo-Su 08:30-20:00\"\n    }\n    </script>\n  </head>\n  <body class=\"bg-[#F7F7F7] text-[#111111] antialiased selection:bg-[#F58220] selection:text-white\">\n    <div id=\"root\"></div>\n    <script type=\"module\" src=\"/src/main.tsx\"></script>\n  </body>\n</html>\n\n"
};
